import decimal,re
def summarize(batches,rule):
    if rule!='invoice-v1':raise ValueError('unsupported billing rule')
    units={'USD':decimal.Decimal('0.01'),'EUR':decimal.Decimal('0.01'),'JPY':decimal.Decimal('1')}
    total={};count=0
    with decimal.localcontext(decimal.Context(prec=50,rounding=decimal.ROUND_HALF_EVEN)):
        for batch in batches:
            for row in batch:
                count+=1
                if count>10000 or not isinstance(row,dict) or set(row)!={'currency','amount'}:raise ValueError('bounded exact billing rows')
                currency=row['currency'];amount=row['amount']
                if not isinstance(currency,str) or currency not in units or not isinstance(amount,str) or not re.fullmatch(r'-?(?:0|[1-9][0-9]{0,29})(?:\.[0-9]{1,6})?',amount):raise ValueError('exact decimal and approved currency')
                value=decimal.Decimal(amount)
                total[currency]=total.get(currency,decimal.Decimal(0))+value
